var a={en:`Shoppers may return order lines within 14 days; warehouse inspection can approve part of a return and reject damaged items.`,ua:`Покупці повертають окремі позиції протягом 14 днів; склад може погодити частину повернення та відхилити пошкоджені речі.`};var t={en:[`Add return authorization, inspection and refund states.`,`Link partial refunds to original order lines and payment IDs.`,`Define webhook retries, audit and conditional restocking.`],ua:[`Додай авторизацію повернення, огляд і стани відшкодування.`,`Прив’яжи часткові виплати до позицій і платіжних ID.`,`Визнач повтори вебхуків, аудит і умовне поповнення складу.`]};var r=[{en:`Duplicate webhooks do not pay twice.`,ua:`Повторний вебхук не повертає гроші двічі.`},{en:`Only accepted inspected goods are restocked.`,ua:`Лише перевірені схвалені товари повертаються на склад.`}];var i={scenario:a,tasks:t,checks:r};export{r as checks,i as default,a as scenario,t as tasks};